edits.before:
self._onKeyChange = function(e)
{
    e = e || window.event;

    if (self.isVisible()) {

        switch(e.keyCode){
            case 13:
            case 27:
                if (opts.field) {
                    opts.field.blur();
                }
                break;
            case 37:
                self.adjustDate('subtract', 1);
                break;
            case 38:
                self.adjustDate('subtract', 7);
                break;
            case 39:
                self.adjustDate('add', 1);
                break;
            case 40:
                self.adjustDate('add', 7);
                break;
            case 8:
            case 46:
                self.setDate(null);
                break;
        }
    }
};

edits.after:
self._onKeyChange = function(e)
{
    e = e || window.event;

    if (self.isVisible()) {

        function isValidDate(d) {
            if (self._o.minDate && d < self._o.minDate) return false;
            if (self._o.maxDate && d > self._o.maxDate) return false;
            if (typeof self._o.disableDayFn === 'function' && self._o.disableDayFn(d)) return false;
            return true;
        }

        switch(e.keyCode){
            case 13:
            case 27:
                if (opts.field) {
                    opts.field.blur();
                }
                break;
            case 37:
                var prev = self.getDate();
                do {
                    self.adjustDate('subtract', 1);
                    var curr = self.getDate();
                    if (!curr) break;
                    if (curr.getTime() === prev.getTime()) break;
                    prev = curr;
                } while (!isValidDate(curr));
                break;
            case 38:
                var prev = self.getDate();
                do {
                    self.adjustDate('subtract', 7);
                    var curr = self.getDate();
                    if (!curr) break;
                    if (curr.getTime() === prev.getTime()) break;
                    prev = curr;
                } while (!isValidDate(curr));
                break;
            case 39:
                var prev = self.getDate();
                do {
                    self.adjustDate('add', 1);
                    var curr = self.getDate();
                    if (!curr) break;
                    if (curr.getTime() === prev.getTime()) break;
                    prev = curr;
                } while (!isValidDate(curr));
                break;
            case 40:
                var prev = self.getDate();
                do {
                    self.adjustDate('add', 7);
                    var curr = self.getDate();
                    if (!curr) break;
                    if (curr.getTime() === prev.getTime()) break;
                    prev = curr;
                } while (!isValidDate(curr));
                break;
            case 8:
            case 46:
                self.setDate(null);
                break;
        }
    }
};
